/* ===================== BÀI 41 · I2C qua GPIO ===================== */
/* Bài 41 · I2C qua GPIO (AMTS-EMB-001-M11-L01, MC51-041) — sinh bởi tools/author/mcu8051/l41.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const PR41=[{"label":"Ví dụ: Gọi địa chỉ PCF8574 và đọc ACK","code":"; Ví dụ 1: gọi địa chỉ PCF8574 (20H) và đọc ACK\n; SDA = P1.0, SCL = P1.1 (giả định nối dây: hai đường có\n; điện trở kéo lên ngoài; ghi 1 = nhả đường, ghi 0 = kéo xuống)\n        ORG     0000H\n        SJMP    MAIN\n; --- I2C_START: SDA 1->0 khi SCL = 1, rồi kéo SCL xuống ---\nI2C_START:\n        SETB    P1.0                    ; SDA = 1\n        SETB    P1.1                    ; SCL = 1\n        CLR     P1.0                    ; START\n        CLR     P1.1                    ; SCL = 0: bus bận\n        RET\n; --- I2C_STOP: SDA 0->1 khi SCL = 1 ---\nI2C_STOP:\n        CLR     P1.0                    ; SDA = 0 (lúc SCL = 0)\n        SETB    P1.1                    ; SCL = 1\n        SETB    P1.0                    ; STOP: nhả SDA\n        RET\n; --- I2C_WRITE: gửi A, bit 7 trước; ra CY = bit ACK\n;     (0 = có ACK, 1 = NACK). Dùng R7, A bị đổi. ---\nI2C_WRITE:\n        MOV     R7,#8\nWB:     RLC     A                       ; bit cao nhất vào CY\n        MOV     P1.0,C                  ; đặt SDA khi SCL = 0\n        SETB    P1.1                    ; SCL = 1: slave lấy mẫu\n        CLR     P1.1                    ; SCL = 0\n        DJNZ    R7,WB\n        SETB    P1.0                    ; nhả SDA cho slave trả lời\n        SETB    P1.1                    ; xung SCL thứ 9\n        MOV     C,P1.0                  ; đọc ACK: 0 = có slave nhận\n        CLR     P1.1\n        RET\nMAIN:   LCALL   I2C_START\n        MOV     A,#40H                  ; 0100 000 + R/W = 0 (ghi)\n        LCALL   I2C_WRITE               ; CY = bit ACK\n        CLR     A\n        RLC     A                       ; A = CY\n        MOV     30H,A                   ; 30H = 00H: ACK, 01H: NACK\n        LCALL   I2C_STOP\n        SJMP    $\n        END\n","note":"Gửi byte 40H = địa chỉ 20H + bit ghi. Đoán trước: ở xung SCL thứ 9, SDA ở mức nào? PCF8574 trả lời bằng cách kéo SDA xuống (ACK), nên 30H = 00H. Bỏ thiết bị đi (chạy trên s51) thì không ai kéo: 30H = 01H. 86 chu kỳ trong cả hai trường hợp vì chương trình không rẽ nhánh.","dev":{"i2c":{"devs":[{"type":"pcf8574","addr":32}]}},"fosc":12000000},{"label":"Ví dụ: Ghi một byte ra PCF8574","code":"; Ví dụ 2: ghi một byte ra PCF8574, bật 4 LED\n; SDA = P1.0, SCL = P1.1 (giả định nối dây: hai đường có\n; điện trở kéo lên ngoài; ghi 1 = nhả đường, ghi 0 = kéo xuống)\n        ORG     0000H\n        SJMP    MAIN\n; --- I2C_START: SDA 1->0 khi SCL = 1, rồi kéo SCL xuống ---\nI2C_START:\n        SETB    P1.0                    ; SDA = 1\n        SETB    P1.1                    ; SCL = 1\n        CLR     P1.0                    ; START\n        CLR     P1.1                    ; SCL = 0: bus bận\n        RET\n; --- I2C_STOP: SDA 0->1 khi SCL = 1 ---\nI2C_STOP:\n        CLR     P1.0                    ; SDA = 0 (lúc SCL = 0)\n        SETB    P1.1                    ; SCL = 1\n        SETB    P1.0                    ; STOP: nhả SDA\n        RET\n; --- I2C_WRITE: gửi A, bit 7 trước; ra CY = bit ACK\n;     (0 = có ACK, 1 = NACK). Dùng R7, A bị đổi. ---\nI2C_WRITE:\n        MOV     R7,#8\nWB:     RLC     A                       ; bit cao nhất vào CY\n        MOV     P1.0,C                  ; đặt SDA khi SCL = 0\n        SETB    P1.1                    ; SCL = 1: slave lấy mẫu\n        CLR     P1.1                    ; SCL = 0\n        DJNZ    R7,WB\n        SETB    P1.0                    ; nhả SDA cho slave trả lời\n        SETB    P1.1                    ; xung SCL thứ 9\n        MOV     C,P1.0                  ; đọc ACK: 0 = có slave nhận\n        CLR     P1.1\n        RET\nMAIN:   LCALL   I2C_START\n        MOV     A,#40H                  ; địa chỉ 20H + ghi\n        LCALL   I2C_WRITE\n        JC      NACK1                   ; không ai nhận địa chỉ\n        MOV     A,#0F0H                 ; P3..P0 = 0: 4 LED sáng\n        LCALL   I2C_WRITE\n        JC      NACK2                   ; slave không nhận dữ liệu\n        MOV     30H,#00H                ; mã kết quả: thành công\n        SJMP    XONG\nNACK1:  MOV     30H,#01H                ; lỗi 1: NACK ở byte địa chỉ\n        SJMP    XONG\nNACK2:  MOV     30H,#02H                ; lỗi 2: NACK ở byte dữ liệu\nXONG:   LCALL   I2C_STOP                ; luôn trả bus bằng STOP\n        SJMP    $\n        END\n","note":"Khung đầy đủ: S · 40 · ACK · F0 · ACK · P. Sau STOP, 4 LED P3…P0 của PCF8574 sáng (F0H: bốn bit thấp = 0). Theo dõi CY sau mỗi lần gọi I2C_WRITE: CY = 0 nên JC không nhảy. 157 chu kỳ; nếu không có thiết bị, chương trình rẽ sang NACK1 sau 89 chu kỳ.","dev":{"i2c":{"devs":[{"type":"pcf8574","addr":32}]}},"fosc":12000000},{"label":"Bẫy: Đổi SDA khi SCL đang ở mức 1","code":"; Ví dụ 3 (bẫy): đổi SDA khi SCL đang ở mức 1\n; SDA = P1.0, SCL = P1.1 (giả định nối dây: hai đường có\n; điện trở kéo lên ngoài; ghi 1 = nhả đường, ghi 0 = kéo xuống)\n        ORG     0000H\n        SJMP    MAIN\n; --- I2C_START: SDA 1->0 khi SCL = 1, rồi kéo SCL xuống ---\nI2C_START:\n        SETB    P1.0                    ; SDA = 1\n        SETB    P1.1                    ; SCL = 1\n        CLR     P1.0                    ; START\n        CLR     P1.1                    ; SCL = 0: bus bận\n        RET\n; --- I2C_STOP: SDA 0->1 khi SCL = 1 ---\nI2C_STOP:\n        CLR     P1.0                    ; SDA = 0 (lúc SCL = 0)\n        SETB    P1.1                    ; SCL = 1\n        SETB    P1.0                    ; STOP: nhả SDA\n        RET\n; --- I2C_WRITE: gửi A, bit 7 trước; ra CY = bit ACK\n;     (0 = có ACK, 1 = NACK). Dùng R7, A bị đổi. ---\nI2C_WRITE:\n        MOV     R7,#8\nWB:     RLC     A                       ; bit cao nhất vào CY\n        SETB    P1.1                    ; SAI THỨ TỰ: SCL lên trước\n        MOV     P1.0,C                  ; SDA đổi khi SCL = 1\n        CLR     P1.1                    ; SCL = 0\n        DJNZ    R7,WB\n        SETB    P1.0                    ; nhả SDA cho slave trả lời\n        SETB    P1.1                    ; xung SCL thứ 9\n        MOV     C,P1.0                  ; đọc ACK: 0 = có slave nhận\n        CLR     P1.1\n        RET\nMAIN:   LCALL   I2C_START\n        MOV     A,#40H                  ; địa chỉ 20H + ghi\n        LCALL   I2C_WRITE\n        JC      NACK1                   ; không ai nhận địa chỉ\n        MOV     A,#0F0H                 ; P3..P0 = 0: 4 LED sáng\n        LCALL   I2C_WRITE\n        JC      NACK2                   ; slave không nhận dữ liệu\n        MOV     30H,#00H                ; mã kết quả: thành công\n        SJMP    XONG\nNACK1:  MOV     30H,#01H                ; lỗi 1: NACK ở byte địa chỉ\n        SJMP    XONG\nNACK2:  MOV     30H,#02H                ; lỗi 2: NACK ở byte dữ liệu\nXONG:   LCALL   I2C_STOP                ; luôn trả bus bằng STOP\n        SJMP    $\n        END\n","note":"Vòng gửi bit đưa SCL lên TRƯỚC rồi mới đổi SDA. Máy phân tích thấy SDA đổi khi SCL = 1: bit 6 = 1 tạo STOP giả, bit 5 = 0 tạo START giả. Kết quả giải mã “S P S P”, slave không nhận được byte địa chỉ nào, 30H = 01H.","dev":{"i2c":{"devs":[{"type":"pcf8574","addr":32}]}},"fosc":12000000},{"label":"Ví dụ: Thêm NOP cho đúng Standard-mode","code":"; Ví dụ 4: thêm NOP cho đúng Standard-mode ở 12 MHz\n; SDA = P1.0, SCL = P1.1 (giả định nối dây: hai đường có\n; điện trở kéo lên ngoài; ghi 1 = nhả đường, ghi 0 = kéo xuống)\n        ORG     0000H\n        SJMP    MAIN\n; --- I2C_START: giữ đủ tSU;STA >= 4,7 us, tHD;STA >= 4 us ---\nI2C_START:\n        SETB    P1.0                    ; SDA = 1\n        SETB    P1.1                    ; SCL = 1\n        NOP\n        NOP\n        NOP\n        NOP\n        CLR     P1.0                    ; START (5 us sau khi SCL lên)\n        NOP\n        NOP\n        NOP\n        CLR     P1.1                    ; 4 us sau START\n        RET\n; --- I2C_STOP: tSU;STO >= 4 us ---\nI2C_STOP:\n        CLR     P1.0\n        SETB    P1.1\n        NOP\n        NOP\n        NOP\n        SETB    P1.0                    ; STOP 4 us sau khi SCL lên\n        RET\n; --- I2C_WRITE (Standard-mode): SCL cao 4 us, thấp >= 5 us ---\nI2C_WRITE:\n        MOV     R7,#8\nWB:     RLC     A\n        MOV     P1.0,C                  ; đặt SDA khi SCL = 0\n        SETB    P1.1                    ; SCL = 1\n        NOP                             ; 3 NOP: SCL cao đủ 4 us\n        NOP\n        NOP\n        CLR     P1.1                    ; mỗi bit 10 us -> 100 kHz\n        DJNZ    R7,WB\n        SETB    P1.0                    ; nhả SDA\n        NOP                             ; SCL thấp đủ 5 us\n        SETB    P1.1                    ; xung thứ 9\n        MOV     C,P1.0                  ; đọc ACK\n        NOP\n        NOP                             ; SCL cao đủ 4 us\n        CLR     P1.1\n        RET\nMAIN:   LCALL   I2C_START\n        MOV     A,#40H                  ; địa chỉ 20H + ghi\n        LCALL   I2C_WRITE\n        JC      NACK1                   ; không ai nhận địa chỉ\n        MOV     A,#0F0H                 ; P3..P0 = 0: 4 LED sáng\n        LCALL   I2C_WRITE\n        JC      NACK2                   ; slave không nhận dữ liệu\n        MOV     30H,#00H                ; mã kết quả: thành công\n        SJMP    XONG\nNACK1:  MOV     30H,#01H                ; lỗi 1: NACK ở byte địa chỉ\n        SJMP    XONG\nNACK2:  MOV     30H,#02H                ; lỗi 2: NACK ở byte dữ liệu\nXONG:   LCALL   I2C_STOP                ; luôn trả bus bằng STOP\n        SJMP    $\n        END\n","note":"Thêm NOP vào cả bốn hàm: SCL cao 4 µs, thấp 6 µs (bit dữ liệu) và 5 µs (trước xung 9), START/STOP giữ 4 µs. Máy phân tích không còn cảnh báo. Đổi lại: 221 chu kỳ thay vì 157, mã dài thêm 16 byte.","dev":{"i2c":{"mode":"std","devs":[{"type":"pcf8574","addr":32}]}},"fosc":12000000}];
const sim41=makeSim51(document.getElementById("m51-l41"),{id:"s41",presets:PR41,ram:256});
makeEx51(document.getElementById("ex-l41"),"l41",[{"t":"Byte địa chỉ và địa chỉ dành riêng","d":"<p>Ô <code>30H<\/code> chứa địa chỉ 7 bit của một slave I2C (00H–7FH), ô <code>31H<\/code> chứa hướng truyền: <code>00H<\/code> = ghi, <code>01H<\/code> = đọc. Viết chương trình: (1) ghi vào <code>32H<\/code> byte địa chỉ mà master phải gửi sau START (7 bit địa chỉ ở bit 7…1, bit R/W ở bit 0); (2) ghi <code>33H = 01H<\/code> nếu địa chỉ thuộc hai nhóm dành riêng của chuẩn I2C (0000xxx, tức 00H–07H, và 1111xxx, tức 78H–7FH), ngược lại <code>33H = 00H<\/code>. Ô <code>30H<\/code>, <code>31H<\/code> giữ nguyên. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>30H = 50H<\/code>, <code>31H = 00H<\/code> → <code>32H = A0H<\/code>, <code>33H = 00H<\/code>.<\/p>","start":"        ORG     0000H\n        MOV     A,30H                   ; địa chỉ 7 bit\n        RL      A                       ; dịch lên bit 7..1\n        MOV     32H,A                   ; còn thiếu bit R/W\n; còn thiếu: 33H = 01H nếu địa chỉ dành riêng\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":80,"0x31":0,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":80,"0x31":0,"0x32":160,"0x33":0}}},{"setup":{"iram":{"0x30":80,"0x31":1,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":80,"0x31":1,"0x32":161,"0x33":0}}},{"setup":{"iram":{"0x30":32,"0x31":0,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":32,"0x31":0,"0x32":64,"0x33":0}}},{"setup":{"iram":{"0x30":7,"0x31":1,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":7,"0x31":1,"0x32":15,"0x33":1}}},{"setup":{"iram":{"0x30":8,"0x31":0,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":8,"0x31":0,"0x32":16,"0x33":0}}},{"setup":{"iram":{"0x30":119,"0x31":1,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":119,"0x31":1,"0x32":239,"0x33":0}}},{"setup":{"iram":{"0x30":120,"0x31":0,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":120,"0x31":0,"0x32":240,"0x33":1}}},{"setup":{"iram":{"0x30":0,"0x31":0,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":0,"0x31":0,"0x32":0,"0x33":1}}}]},"hints":["Dịch địa chỉ sang trái 1 bit (RL A là đủ vì bit 7 của địa chỉ 7 bit luôn 0) rồi OR với ô 31H.","Hai nhóm dành riêng chỉ khác nhau ở 4 bit cao của địa chỉ 7 bit (bit 6…3): 0000 hoặc 1111. Lệnh ANL A,#78H giữ đúng 4 bit đó.","Sau khi che còn hai giá trị dành riêng: kiểm cả hai. Ô kết quả có thể chứa rác lúc đầu."],"why":"Byte địa chỉ = địa chỉ 7 bit dịch trái 1 + bit R/W, nên địa chỉ 50H thành A0H (ghi) hoặc A1H (đọc) — đây là nguồn nhầm lẫn hay gặp khi đọc datasheet (có hãng ghi 7 bit, có hãng ghi 8 bit). Hai nhóm 0000xxx và 1111xxx được chuẩn I2C dành cho lời gọi chung, START byte, địa chỉ 10 bit…, không gán cho thiết bị thường; bộ thử 4–7 kiểm đúng hai biên 07H/08H và 77H/78H."},{"t":"Giải mã một khung từ bộ ghi mẫu","d":"<p>Một máy phân tích logic đã lấy mẫu hai đường I2C và chép vào RAM từ <code>40H<\/code>: mỗi ô là một mẫu, bit 1 = SCL, bit 0 = SDA (03H = cả hai ở mức 1). Dãy kết thúc bằng ô <code>0FFH<\/code>. Trước mẫu đầu tiên coi như bus rảnh (03H). Viết chương trình tìm điều kiện START đầu tiên (mẫu trước 03H, mẫu sau 02H: SDA xuống khi SCL = 1), rồi lấy mức SDA ở <b>9 sườn lên<\/b> của SCL sau đó: 8 bit đầu ghép thành byte ở <code>30H<\/code> (bit đầu tiên là bit 7), bit thứ 9 ghi vào <code>31H<\/code> (00H = ACK, 01H = NACK). Sau bit thứ 9, nếu có STOP (mẫu trước 02H, mẫu sau 03H) thì <code>32H = 01H<\/code>, không thì <code>32H = 00H<\/code>. Nếu cả dãy không có START: <code>30H = 00H<\/code>, <code>31H = 0FFH<\/code>, <code>32H = 00H<\/code>. Đề bảo đảm có START thì có đủ 9 sườn lên.<\/p><p>Ví dụ: dãy 03 02 00 01 03 01 00 02 00 … (khung A0H, ACK, STOP) → <code>30H = A0H<\/code>, <code>31H = 00H<\/code>, <code>32H = 01H<\/code>.<\/p>","start":"; Mỗi ô từ 40H là một mẫu: bit 1 = SCL, bit 0 = SDA.\n; Hết dãy: ô có giá trị 0FFH.\n        ORG     0000H\n        MOV     30H,#00H\n        MOV     31H,#0FFH               ; mặc định: không có START\n        MOV     32H,#00H\n        MOV     R0,#40H\n        MOV     R2,#03H                 ; mẫu trước: bus rảnh (SCL = SDA = 1)\nTIM:    MOV     A,@R0                   ; tìm START\n        INC     R0\n        CJNE    A,#0FFH,KT1\n        SJMP    XONG                    ; hết mẫu\nKT1:                                    ; TODO: nếu mẫu trước = 03H và mẫu nay =\n                                        ; 02H thì là START\n        MOV     R2,A\n        SJMP    TIM\n; TODO: sau START, lấy SDA ở 9 sườn lên của SCL:\n;       8 bit đầu vào 30H (bit 7 trước), bit 9 vào 31H\n; TODO: tìm STOP (mẫu trước 02H, mẫu nay 03H): 32H = 01H\nXONG:   SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x40":3,"0x41":2,"0x42":0,"0x43":1,"0x44":3,"0x45":1,"0x46":0,"0x47":2,"0x48":0,"0x49":1,"0x4A":3,"0x4B":1,"0x4C":0,"0x4D":2,"0x4E":0,"0x4F":0,"0x50":2,"0x51":0,"0x52":0,"0x53":2,"0x54":0,"0x55":0,"0x56":2,"0x57":0,"0x58":0,"0x59":2,"0x5A":0,"0x5B":0,"0x5C":2,"0x5D":0,"0x5E":0,"0x5F":2,"0x60":3,"0x61":255,"0x30":238,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":160,"0x31":0,"0x32":1}}},{"setup":{"iram":{"0x40":3,"0x41":2,"0x42":0,"0x43":0,"0x44":2,"0x45":0,"0x46":1,"0x47":3,"0x48":1,"0x49":0,"0x4A":2,"0x4B":0,"0x4C":0,"0x4D":2,"0x4E":0,"0x4F":0,"0x50":2,"0x51":0,"0x52":0,"0x53":2,"0x54":0,"0x55":0,"0x56":2,"0x57":0,"0x58":1,"0x59":3,"0x5A":1,"0x5B":1,"0x5C":3,"0x5D":1,"0x5E":0,"0x5F":2,"0x60":3,"0x61":255,"0x30":238,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":65,"0x31":1,"0x32":1}}},{"setup":{"iram":{"0x40":3,"0x41":2,"0x42":0,"0x43":1,"0x44":3,"0x45":1,"0x46":1,"0x47":3,"0x48":1,"0x49":1,"0x4A":3,"0x4B":1,"0x4C":1,"0x4D":3,"0x4E":1,"0x4F":1,"0x50":3,"0x51":1,"0x52":1,"0x53":3,"0x54":1,"0x55":1,"0x56":3,"0x57":1,"0x58":1,"0x59":3,"0x5A":1,"0x5B":0,"0x5C":2,"0x5D":0,"0x5E":255,"0x30":238,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":255,"0x31":0,"0x32":0}}},{"setup":{"iram":{"0x40":3,"0x41":2,"0x42":0,"0x43":1,"0x44":0,"0x45":2,"0x46":0,"0x47":1,"0x48":0,"0x49":2,"0x4A":0,"0x4B":1,"0x4C":0,"0x4D":2,"0x4E":0,"0x4F":1,"0x50":0,"0x51":2,"0x52":0,"0x53":1,"0x54":0,"0x55":2,"0x56":0,"0x57":1,"0x58":0,"0x59":2,"0x5A":0,"0x5B":1,"0x5C":0,"0x5D":2,"0x5E":0,"0x5F":1,"0x60":0,"0x61":2,"0x62":0,"0x63":1,"0x64":0,"0x65":2,"0x66":0,"0x67":0,"0x68":2,"0x69":3,"0x6A":255,"0x30":238,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":0,"0x31":0,"0x32":1}}},{"setup":{"iram":{"0x40":3,"0x41":1,"0x42":0,"0x43":2,"0x44":3,"0x45":3,"0x46":2,"0x47":0,"0x48":0,"0x49":2,"0x4A":0,"0x4B":1,"0x4C":3,"0x4D":1,"0x4E":0,"0x4F":2,"0x50":0,"0x51":1,"0x52":3,"0x53":1,"0x54":1,"0x55":3,"0x56":1,"0x57":0,"0x58":2,"0x59":0,"0x5A":1,"0x5B":3,"0x5C":1,"0x5D":0,"0x5E":2,"0x5F":0,"0x60":1,"0x61":3,"0x62":1,"0x63":0,"0x64":2,"0x65":3,"0x66":255,"0x30":238,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":90,"0x31":1,"0x32":1}}},{"setup":{"iram":{"0x40":3,"0x41":3,"0x42":1,"0x43":3,"0x44":1,"0x45":3,"0x46":1,"0x47":1,"0x48":255,"0x30":238,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":0,"0x31":255,"0x32":0}}},{"setup":{"iram":{"0x40":3,"0x41":3,"0x42":2,"0x43":2,"0x44":0,"0x45":0,"0x46":0,"0x47":0,"0x48":2,"0x49":2,"0x4A":0,"0x4B":0,"0x4C":0,"0x4D":0,"0x4E":2,"0x4F":2,"0x50":0,"0x51":0,"0x52":1,"0x53":1,"0x54":3,"0x55":3,"0x56":1,"0x57":1,"0x58":1,"0x59":1,"0x5A":3,"0x5B":3,"0x5C":1,"0x5D":1,"0x5E":1,"0x5F":1,"0x60":3,"0x61":3,"0x62":1,"0x63":1,"0x64":1,"0x65":1,"0x66":3,"0x67":3,"0x68":1,"0x69":1,"0x6A":0,"0x6B":0,"0x6C":2,"0x6D":2,"0x6E":0,"0x6F":0,"0x70":0,"0x71":0,"0x72":2,"0x73":2,"0x74":0,"0x75":0,"0x76":0,"0x77":0,"0x78":2,"0x79":2,"0x7A":0,"0x7B":0,"0x7C":255,"0x30":238,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":60,"0x31":0,"0x32":0}}}]},"hints":["Giữ mẫu trước trong một thanh ghi (R2). START = mẫu trước 03H và mẫu nay 02H; hai lệnh CJNE liên tiếp kiểm được điều kiện này.","Sườn lên của SCL: bit 1 của (mẫu trước XOR mẫu nay) AND mẫu nay bằng 1. Mỗi mẫu lấy mức đều phải cập nhật “mẫu trước”, kể cả khi không có sườn.","Ở mỗi sườn lên của SCL, đưa SDA qua CY rồi dồn vào byte kết quả; đủ 9 bit thì bit thứ 9 là ACK."],"why":"Slave chỉ lấy mẫu SDA ở sườn lên của SCL; SDA đổi khi SCL = 0 (bộ thử 4) không phải dữ liệu, và mỗi mức được lấy mẫu nhiều lần (bộ thử 7) cũng chỉ tính một sườn. Chỉ SDA đổi khi SCL = 1 mới là START/STOP: ở bộ thử 5, SDA xuống khi SCL = 0 rồi SCL lên không phải START. Đây chính là cách máy phân tích logic và slave “đọc” bus."},{"t":"Gửi byte có đọc lại SDA, dưới 120 chu kỳ","d":"<p>SDA = P1.0, SCL = P1.1, bus đang rảnh (cả hai đường ở 1). Code mẫu tạo START, gửi byte ở <code>30H<\/code> (bit 7 trước), đọc bit thứ 9 vào <code>31H<\/code> rồi tạo STOP, nhưng chậm và <b>không<\/b> phát hiện được bus hỏng. Hãy sửa để: (1) sau khi đưa SCL lên ở mỗi bit, nếu bit vừa gửi là 1 mà đọc lại chân SDA được 0 (một thiết bị khác đang giữ SDA ở mức thấp) thì dừng gửi ngay, nhả SDA (SCL đang ở 1), ghi <code>31H = 02H<\/code>; (2) nếu gửi đủ 8 bit thì <code>31H<\/code> = bit thứ 9 (00H ACK, 01H NACK) rồi tạo STOP; (3) trong mọi trường hợp <code>32H<\/code> = số bit đã gửi trót lọt trước khi dừng (0…8) và cuối cùng chốt P1 = FFH; (4) chạy không quá <b>120 chu kỳ máy<\/b> (tính cả một lần <code>SJMP $<\/code>), mã không quá <b>56 byte<\/b>.<\/p><p>Bộ thử có “SDA bị giữ 0” đặt chân P1.0 luôn ở mức 0 từ bên ngoài. Ví dụ: <code>30H = 20H<\/code>, SDA bị giữ 0 → hai bit 0 đầu gửi được, bit thứ ba là 1 thì hỏng: <code>31H = 02H<\/code>, <code>32H = 02H<\/code>.<\/p>","start":"; SDA = P1.0, SCL = P1.1. Gửi đúng nhưng chậm và CHƯA đọc lại SDA.\n        ORG     0000H\n        MOV     R5,30H                  ; byte cần gửi\n        MOV     R4,#80H                 ; mặt nạ: bit 7 trước\n        MOV     R6,#0                   ; số bit đã gửi\n        CLR     P1.0                    ; START\n        CLR     P1.1\nGUI:    MOV     A,R5\n        ANL     A,R4                    ; lấy bit đang gửi\n        JZ      BIT0\n        SETB    P1.0                    ; bit 1\n        SJMP    CLK\nBIT0:   CLR     P1.0                    ; bit 0\nCLK:    SETB    P1.1                    ; SCL = 1\n; TODO: gửi 1 mà đọc lại SDA = 0 thì 31H = 02H và dừng\n        CLR     P1.1\n        INC     R6\n        MOV     A,R4\n        RR      A                       ; mặt nạ sang bit kế\n        MOV     R4,A\n        CJNE    R6,#8,GUI\n        SETB    P1.0                    ; nhả SDA, xung thứ 9\n        SETB    P1.1\n        MOV     C,P1.0\n        CLR     A\n        RLC     A\n        MOV     31H,A                   ; 00H ACK, 01H NACK\n        CLR     P1.1                    ; STOP\n        CLR     P1.0\n        SETB    P1.1\n        SETB    P1.0\n        MOV     32H,R6\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":160,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":160,"0x31":1,"0x32":8},"ports":{"P1":255}}},{"setup":{"iram":{"0x30":160,"0x31":238,"0x32":238},"pins":{"P1":254}},"expect":{"iram":{"0x30":160,"0x31":2,"0x32":0}}},{"setup":{"iram":{"0x30":32,"0x31":238,"0x32":238},"pins":{"P1":254}},"expect":{"iram":{"0x30":32,"0x31":2,"0x32":2}}},{"setup":{"iram":{"0x30":0,"0x31":238,"0x32":238},"pins":{"P1":254}},"expect":{"iram":{"0x30":0,"0x31":0,"0x32":8}}},{"setup":{"iram":{"0x30":1,"0x31":238,"0x32":238},"pins":{"P1":254}},"expect":{"iram":{"0x30":1,"0x31":2,"0x32":7}}},{"setup":{"iram":{"0x30":255,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":255,"0x31":1,"0x32":8},"ports":{"P1":255}}},{"setup":{"iram":{"0x30":85,"0x31":238,"0x32":238},"pins":{"P1":254}},"expect":{"iram":{"0x30":85,"0x31":2,"0x32":1}}}],"maxCyc":120,"maxBytes":56},"hints":["Đọc lại ngay sau SETB P1.1: lệnh JNB P1.0,… đọc chân (không đọc chốt), nên thấy được mức do thiết bị khác kéo xuống.","Chỉ kiểm khi bit vừa gửi là 1: sau RLC A, bit nằm ở CY; JNC bỏ qua phần kiểm. Gửi 0 mà đọc 0 là bình thường.","Đưa bit ra bằng một lệnh xoay qua CY rồi ghi C thẳng vào chân, thay cho tách bit bằng mặt nạ."],"why":"Chân cổng 8051 đọc mức thật trên dây (chốt AND tín hiệu ngoài). Master I2C đọc lại SDA sau khi nhả nó ra là cách phát hiện bus bị giữ hoặc mất quyền điều khiển khi có hai master (arbitration). Bộ thử 4 cho thấy giới hạn: gửi toàn 0 thì không phát hiện được, và xung thứ 9 đọc 0 trông như ACK. Dịch bit bằng RLC A + MOV P1.0,C thay cho mặt nạ đưa vòng lặp xuống 10–12 chu kỳ mỗi bit, cả byte chạy tối đa 116 chu kỳ."}]);

makeQuiz("quiz41","score41",[{"q": "Trên bus I2C, PCF8574 đang kéo SDA xuống 0 trong khi chốt P1.0 của 8051 bằng 1. Lệnh MOV C,P1.0 cho CY bằng bao nhiêu?", "o": ["1, vì lệnh đọc lại giá trị chốt đã ghi", "Không xác định vì hai ngõ ra chọi nhau", "1, vì điện trở kéo lên thắng transistor kéo xuống", "0, vì lệnh đọc mức chân và đường là AND của mọi thiết bị"], "a": 3, "e": "Ngõ ra cực máng hở chỉ kéo xuống hoặc buông, nên đường ở 0 khi có bất kỳ thiết bị nào kéo (wired-AND), không có chọi nhau. MOV C,P1.0 đọc chân, không đọc chốt."}, {"q": "Master muốn đọc từ slave có địa chỉ 7 bit là 50H. Byte nó gửi ngay sau START là gì?", "o": ["A1H", "50H", "A0H", "51H"], "a": 0, "e": "Địa chỉ 7 bit nằm ở bit 7…1: 50H dịch trái 1 = A0H; bit 0 = 1 cho đọc nên byte là A1H. A0H là byte để ghi."}, {"q": "Vòng gửi bit của I2C_WRITE (RLC A, MOV P1.0,C, SETB P1.1, CLR P1.1, DJNZ R7) chạy ở thạch anh 12 MHz. SCL có tần số khoảng bao nhiêu?", "o": ["1 MHz", "143 kHz", "100 kHz", "500 kHz"], "a": 1, "e": "Mỗi bit tốn 1 + 2 + 1 + 1 + 2 = 7 chu kỳ máy = 7 µs ở 12 MHz, nên f = 1/7 µs ≈ 143 kHz: vượt 100 kHz của Standard-mode nhưng dưới 400 kHz của Fast-mode."}, {"q": "Trong vòng gửi bit, đổi thứ tự thành SETB P1.1 rồi mới MOV P1.0,C. Điều gì xảy ra khi bit kế tiếp khác bit trước?", "o": ["Không sao, slave lấy mẫu ở sườn xuống", "Chỉ chậm hơn 1 chu kỳ máy mỗi bit", "SDA đổi khi SCL = 1, slave hiểu là START hoặc STOP", "Trình dịch báo lỗi thứ tự lệnh"], "a": 2, "e": "Khi SCL = 1, SDA đổi từ 1 xuống 0 là START, từ 0 lên 1 là STOP. Slave reset khung giữa chừng (ví dụ 3: “S P S P”). Slave lấy mẫu ở sườn lên, nên bit phải đặt khi SCL = 0."}, {"q": "Gửi địa chỉ xong, driver đọc được NACK. Việc nên làm tiếp theo là gì?", "o": ["Tạo STOP để trả bus rồi báo mã lỗi cho chương trình gọi", "Gửi tiếp byte dữ liệu, slave sẽ nhận sau", "Dừng chương trình ngay, giữ nguyên SDA và SCL", "Gửi lại byte địa chỉ mà không cần START"], "a": 0, "e": "NACK ở byte địa chỉ nghĩa là không có slave nào nhận (sai địa chỉ, chưa cắm, hoặc đang bận). Driver luôn kết thúc khung bằng STOP để bus rảnh, rồi trả mã lỗi; có thể thử lại sau bằng một START mới."}]);

